// Package fixture holds one notebook with its blobs, for the tests of
// mdnotebook and the gallery demo of the widget that draws one (ADR-0371).
// The files are generated by collecting a draft against a server that is a
// function: `go test -run TestFixture -update` in this directory rewrites
// them, and the same test without the flag fails when they differ from
// what collection writes.
package fixture

import (
	"embed"
	"io/fs"
)

//go:embed w45.md w45.blobs
var files embed.FS

// Name is the notebook's file in [FS].
const Name = "w45.md"

// FS is the notebook's directory: the text and its blobs.
func FS() fs.FS { return files }
